/**
 * Unit tests for DateTimeZone.forID(String id)
 */
public class DateTimeZone_forID_TriageGen0Test {







    @Test
    public void testForID_PositiveOffset_ReturnsFixedOffsetZone() {
        // Testing the branch: if (id.startsWith("+"))
        // +01:00 is a valid offset format
        String id = "+01:00";
        DateTimeZone result = DateTimeZone.forID(id);
        Assert.assertNotNull(result);
        // The code calls printOffset(offset) which might normalize the ID
        // We verify it is a fixed offset zone
        Assert.assertTrue(result.isFixed());
        Assert.assertNotEquals(DateTimeZone.UTC, result);
    }








}

